      return;
    }

    if (!projectName.trim()) {
      alert("Mohon lengkapi Nama Proyek Penjaminan di bagian atas form.");
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }

    if (!contractValue || parseFloat(contractValue) <= 0) {
      alert("Mohon isi Nilai Kontrak SPK dengan nilai positif.");
      return;
    }

    setLoading(true);

    const formData = new FormData();
    formData.append("company_name", companyName);
    formData.append("project_name", projectName);
    formData.append("contract_value", parseFloat(contractValue) || 0.0);
    formData.append("project_type", projectType);
    formData.append("years_operating", parseInt(yearsOperating) || 0);
    formData.append("successful_projects", parseInt(successfulProjects) || 0);
    formData.append("slik_collectibility", parseInt(slikCollectibility) || 1);
    formData.append("blacklisted", blacklisted);
    formData.append("financial_manipulation", financialManipulation);

    try {
      const response = await fetch("http://127.0.0.1:8000/api/prospects", {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: formData
      });

      if (response.ok) {
        alert("Prospek penjaminan berhasil didaftarkan. Silakan unggah dokumen wajib.");
        setActiveView("daftar");
      } else {
        const err = await response.json();
        alert("Error: " + (err.detail || "Gagal mendaftarkan prospek."));
      }
    } catch (e) {
      alert("Gagal menambahkan prospek. Pastikan koneksi ke server berjalan.");
    } finally {
      setLoading(false);
    }
  };"

